//! 🧪️ The actual native output cursor keeps the original nonempty media body through paid wire and snapshot closure.
use super::*;
use semio_framework_job::{StepBudget,OperationId,Generation,JobPayloadAuthority,OriginalCallerSourceParent};
use semio_framework_async::CancelToken;
use crate::render_snapshot::{RenderSnapshot,RenderSnapshotSink};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
thread_local!{static ORIGINAL_CLOCK:std::cell::Cell<u64>=const{std::cell::Cell::new(0)};}
fn clock()->Option<u64>{ORIGINAL_CLOCK.with(|clock|Some(clock.get()))}
fn delta(before:RetainedCloneProgress,after:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes}}
fn remaining(stock:RetainedCloneGrant,spent:RetainedCloneProgress)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:stock.maximum_items-spent.copied_items,maximum_copy_bytes:stock.maximum_copy_bytes-spent.copied_bytes,maximum_capacity_bytes:stock.maximum_capacity_bytes-spent.retained_capacity_bytes,maximum_release_bytes:stock.maximum_release_bytes-spent.released_bytes,maximum_depth:stock.maximum_depth}}
#[test]
fn original_browser_nonempty_output_same_media_system_denials_and_full_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/🧊️wgpu/🌐️browser-worker/📤️output/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(law["caller"]["stock"].clone()).unwrap();
 for copy in [1,3,64]{
  ORIGINAL_CLOCK.with(|clock|clock.set(law["caller"]["clockUs"].as_u64().unwrap()));let(operation,generation)=(OperationId(law["caller"]["operation"].as_u64().unwrap()),Generation(law["caller"]["generation"].as_u64().unwrap()));let mut recipient=RetainedCloneProgress::default();let mut born=0;let mut freed=0;
  let((cancel,progress),heap)=observe(||CancelToken::admit_root(remaining(stock,recipient)).unwrap().unwrap());recipient=recipient.checked_add(progress).unwrap();born+=heap.requested_bytes;freed+=heap.released_bytes;
  let((authority,progress),heap)=observe(||JobPayloadAuthority::admit(operation,generation,remaining(stock,recipient)).unwrap().unwrap());recipient=recipient.checked_add(progress).unwrap();born+=heap.requested_bytes;freed+=heap.released_bytes;
  let((mut parent,progress),heap)=observe(||OriginalCallerSourceParent::admit(authority,cancel,remaining(stock,recipient)).ok().unwrap());recipient=recipient.checked_add(progress).unwrap();born+=heap.requested_bytes;freed+=heap.released_bytes;let mut sequence=0;let mut cx=parent.borrow_context(StepBudget::new(law["caller"]["fuel"].as_u64().unwrap(),law["caller"]["deadlineUs"].as_u64().unwrap(),stock),clock,&mut sequence,&mut recipient).unwrap();let identity=(cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity());
  let(sink,heap)=observe(||{let media=serde_json::from_value(law["wire"]["mediaSlots"].clone()).unwrap();RenderSnapshotSink::new(RenderSnapshot::new(19,ui_render::CursorRequest::Default,semio_framework_ui_wgpu_hosting::cursor::SemioCursor::Default,false,None).with_media_slots(media))});born+=heap.requested_bytes;freed+=heap.released_bytes;cx.consume_retained(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:heap.requested_bytes,released_bytes:heap.released_bytes,..Default::default()}).unwrap();let snapshot=sink.acquire();let pointer=snapshot.media_slots.as_ptr();let props=match &snapshot.media_slots[0].props{semio_framework_value::DslValue::Object(entries)=>entries.as_ptr(),_=>panic!("original fixture props must remain an object")};drop(snapshot);
  let before=cx.retained_progress();let(loan,heap)=observe(||sink.acquire_output_on_original_caller(&mut cx).unwrap().unwrap());let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));let mut output=OriginalBrowserOutput::new(BrowserTickOutput{presentation_generation:law["wire"]["presentationGeneration"].as_str().unwrap().parse().unwrap(),media_slots:BrowserMediaOutput::Snapshot(loan),cursor:"default",fullscreen:None,request_frame:true,next_deadline_delay_ms:Some(1.25),continue_frame:true,progress:0.5,quarantined:false,fault_code:None,fault_detail:None});
  for turn in 0..4000000{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let demand=output.advance_demands(grant.maximum_copy_bytes).unwrap();for axis in 0..5{let extent=match axis{0=>1,1=>demand.copy_bytes,2=>demand.capacity_bytes,3=>demand.release_bytes,_=>demand.depth};if extent==0{continue}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=demand.copy_bytes-1,2=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3=>denied.maximum_release_bytes=demand.release_bytes-1,_=>denied.maximum_depth=demand.depth-1};let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(denied,|same|output.advance(same)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before)}let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(grant,|same|output.advance(same)));let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!((cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity()),identity);let snapshot=sink.acquire();assert_eq!(snapshot.media_slots.as_ptr(),pointer);assert!(matches!(&snapshot.media_slots[0].props,semio_framework_value::DslValue::Object(entries)if entries.as_ptr()==props));drop(snapshot);if result.unwrap(){break}assert!(turn<3999999)}let actual:serde_json::Value=serde_json::from_slice(output.bytes().unwrap()).unwrap();assert_eq!(actual,law["wire"]);
  for turn in 0..4000000{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(grant,|same|output.close_step(same)));let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;if result.unwrap(){break}assert!(turn<3999999)}assert!(output.terminal_is_empty());let(_,heap)=observe(||drop(output));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for turn in 0..4000000{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(grant,|same|sink.close_on_original_caller(same)));let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;if result.unwrap(){break}assert!(turn<3999999)}let(_,heap)=observe(||drop(sink));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut stock_remaining=cx.retained_grant();drop(cx);for turn in 0..4000000{if parent.terminal_is_empty(){break}let(step,heap)=observe(||parent.close_step(stock_remaining).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;stock_remaining=remaining(stock_remaining,step.progress());assert!(turn<3999999)}assert!(parent.terminal_is_empty());assert_eq!(observe(||drop(parent)).1.released_bytes,0);assert_eq!(born,freed);
 }
}
